const API=window.UNIFIND_API || (location.port==="5000" ? "/api" : `${location.protocol}//${location.hostname}:5000/api`);
const API_ORIGIN=API.replace(/\/api\/?$/,"");
const TOKEN_KEY="unifind_token";
let token=localStorage.getItem(TOKEN_KEY);
let user=null, items=[], listings=[], notes=[], claims=[], conversations=[], activeConversation=null, messagePoll=null, homeFilter="all", marketFilter="all", guestMode=false, lastFocus=null, signupFile=null, signupOcrText="", activeCall=null, callPeerConnection=null, localCallStream=null, callSignalCursor=0, callPoll=null, incomingCallPoll=null, incomingCallPrompt=null, queuedIceCandidates=[];

const esc=s=>String(s??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const cat=s=>({electronics:"Electronics",accessories:"Accessories","id-cards":"ID Cards",books:"Books",other:"Other"}[String(s||"").toLowerCase()]||"Other");
const date=s=>s?new Date(String(s).slice(0,10)+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}):"Date not specified";
const statusText=s=>String(s||"").toLowerCase();
const imageUrl=p=>{if(!p)return ""; if(/^https?:\/\//.test(p)||p.startsWith("data:"))return p; let x=String(p).replaceAll("\\","/"); x=x.replace(/^.*?uploads\//,"/uploads/"); return API_ORIGIN+(x.startsWith("/")?x:"/"+x)};
const api=async(path,opts={})=>{const h=new Headers(opts.headers||{}); if(token)h.set("Authorization","Bearer "+token); if(opts.body && !(opts.body instanceof FormData))h.set("Content-Type","application/json"); const r=await fetch(API+path,{...opts,headers:h}); let d={}; try{d=await r.json()}catch{} if(r.status===401){logout(false); throw new Error("Your session expired. Please sign in again.")} if(!r.ok)throw new Error(d.message||`Request failed (${r.status})`); return d};

function modal(id,on=true){let e=typeof id==="string"?document.getElementById(id):id;if(!e)return;if(on){lastFocus=document.activeElement;e.classList.add("open");e.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";e.querySelector("button,input,textarea,select")?.focus()}else{e.classList.remove("open");e.setAttribute("aria-hidden","true");if(!document.querySelector(".modal-backdrop.open")){document.body.style.overflow="";lastFocus?.focus()}}}
function toast(m){let e=document.getElementById("toast");if(!e)return;e.textContent=m;e.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("show"),3000)}

function mapItem(i){
 return {id:i.id,type:String(i.type||"").toLowerCase(),title:i.title,category:String(i.category||"").toLowerCase(),
 description:i.description,details:i.identifying_characteristics||"",date:i.event_date,time:i.approximate_time||"",
 location:i.location,storageLocation:i.storage_location||"",image:imageUrl(i.image_path),ownerId:i.owner_id,
 ownerName:i.owner_name||"",ownerAvatar:imageUrl(i.owner_avatar),status:statusText(i.status),createdAt:i.created_at,raw:i};
}
async function loadItems(){
 const d=await api("/items?status=all&limit=100"); items=(d.items||[]).map(mapItem);
}
async function loadListings(){const d=await api("/marketplace");listings=(d.listings||[]).map(l=>({...l,image:imageUrl(l.image_path),type:String(l.listing_type||"").toUpperCase(),ownerId:l.owner_id,price:Number(l.price)}));renderMarketplace()}
async function loadNotes(){
 try{const d=await api("/notifications");notes=(d.notifications||[]).map(n=>({id:n.id,title:n.title,body:n.message,time:n.created_at,unread:!n.read_at,type:n.type,itemId:n.item_id}));}
 catch{notes=[]}
}
function media(i,cls="item-image"){let badge=i.status==="returned"?"Returned":i.status==="claimed"?"Claimed":i.type==="lost"?"Lost":"Found",art=i.category==="books"?"📚":i.category==="electronics"?"🎧":i.category==="accessories"?"🎒":"🧸";return `<div class="${cls}">${i.image?`<img src="${esc(i.image)}" alt="Photo of ${esc(i.title)}" loading="lazy" decoding="async" onerror="this.style.display='none';this.parentElement.classList.add('image-fallback')">`:`<div class="placeholder-image" aria-label="No item photo"><span>${art}</span><small>Photo not added</small></div>`}<span class="status-badge ${i.type}">${badge}</span></div>`}
function card(i){
 let own=!!user&&i.ownerId===user.id, claim=!!user&&i.type==="found"&&!own&&i.status==="active";
 return `<article class="item-card">${media(i)}<div class="item-info"><h3>${esc(i.title)}</h3><p class="item-description">${esc(i.description)}</p><div class="item-details"><span>📍 ${esc(i.location)}</span><span>📅 ${date(i.date)}${i.time?" · "+esc(i.time):""}</span>${i.type==="found"&&i.storageLocation?`<span>🔐 Stored at ${esc(i.storageLocation)}</span>`:""}</div><span class="category">${esc(cat(i.category))}</span><div class="card-footer"><button class="card-link" data-view-item="${esc(i.id)}">View details →</button>${claim?`<button class="card-link" data-claim-item="${esc(i.id)}">This might be mine</button>`:own?`<span style="font-size:11px;color:#667085;font-weight:700;">Your report</span>`:""}</div></div></article>`
}
function grid(id,list,title,text){let e=document.getElementById(id);if(!e)return;e.innerHTML=list.length?list.map(card).join(""):`<div class="empty-state"><div class="empty-icon">⌕</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function active(){return items.filter(i=>i.status==="active")}

async function loadClaims(){try{const d=await api("/claims");claims=d.claims||[]}catch{claims=[]}}
function claimStatus(c){return String(c.status||"").toLowerCase()}
function renderClaims(){
 const mine=document.getElementById("myClaimsList"), incoming=document.getElementById("incomingClaimsList");
 const mineRows=claims.filter(c=>c.claimant_id===user.id);
 const incomingRows=claims.filter(c=>c.owner_id===user.id);
 const claimCard=(c,ownerView)=>`<article class="claim-card"><div class="claim-card-main"><h3>${esc(c.title)}</h3><p>${ownerView?`Claim from <strong>${esc(c.claimant_name||"Student")}</strong> · ${esc(c.claimant_member_id||"ID unavailable")} · <strong>${c.claimant_verification_status==='VERIFIED'?'Verified ID':'ID pending'}</strong>`:`Claim submitted · ${esc(c.item_status||"")}`}</p><p>${esc(c.message||"")}</p><span class="claim-status ${claimStatus(c)}">${esc(c.status)}</span></div><div class="claim-actions">${ownerView&&c.status==="PENDING"?`<button class="btn-mini approve" data-approve-claim="${esc(c.id)}">Approve</button><button class="btn-mini reject" data-reject-claim="${esc(c.id)}">Reject</button>`:""}${!ownerView&&c.status==="APPROVED"?`<button class="btn-mini" data-open-chat-user="${esc(c.item_owner_id||"")}" data-chat-item="${esc(c.item_id||"")}">Message finder</button>${c.item_status==="CLAIMED"?`<button class="btn-mini receive" data-received-claim="${esc(c.id)}">I received it</button>`:""}`:""}</div></article>`;
 if(mine)mine.innerHTML=mineRows.length?mineRows.map(c=>claimCard(c,false)).join(""):`<div class="empty-state"><h3>No claims yet</h3><p>When you find a possible match, submit an ownership explanation.</p></div>`;
 if(incoming)incoming.innerHTML=incomingRows.length?incomingRows.map(c=>claimCard(c,true)).join(""):`<div class="empty-state"><h3>No incoming claims</h3><p>Claims for your found items will appear here.</p></div>`;
}
async function reviewClaim(id,status){try{await api(`/claims/${id}`,{method:"PATCH",body:JSON.stringify({status})});toast(status==="APPROVED"?"Claim approved. The claimant can now message you.":"Claim rejected.");await refresh()}catch(e){toast(e.message)}}
async function markReceivedClaim(id){try{await api(`/claims/${id}/received`,{method:"POST"});toast("Receipt confirmed. Item marked returned.");await refresh()}catch(e){toast(e.message)}}
async function loadConversations(){try{const d=await api("/conversations");conversations=d.conversations||[]}catch{conversations=[]}renderConversations()}
function conversationOther(c){return (c.participants||[]).find(p=>p.id!==user.id)||{}}
function avatarMarkup(person,className="conversation-avatar"){const initials=(person?.name||"Student").trim().split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase()||"U";return `<span class="${className} ${person?.avatar?"has-photo":""}" aria-label="${esc(person?.name||"Student")}">${person?.avatar?`<img src="${esc(imageUrl(person.avatar))}" alt="" loading="lazy" decoding="async" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><span class="avatar-initials" hidden>${esc(initials)}</span>`:`<span class="avatar-initials">${esc(initials)}</span>`}</span>`}
function renderConversations(){
 const e=document.getElementById("conversationList"),count=document.getElementById("messageCount"); if(!e)return;
 const unreadTotal=conversations.reduce((sum,c)=>sum+Number(c.unread_count||0),0);if(count){count.textContent=unreadTotal||"";count.style.display=unreadTotal?"grid":"none"}
 const q=(document.getElementById("conversationSearch")?.value||"").toLowerCase();const rows=conversations.filter(c=>{const o=conversationOther(c);return `${o.name||""} ${c.item_title||""} ${c.last_message||""}`.toLowerCase().includes(q)});
 e.innerHTML=rows.length?rows.map(c=>{const o=conversationOther(c);return `<button class="conversation-item ${activeConversation===c.id?"active":""}" data-conversation="${esc(c.id)}">${avatarMarkup(o)}<span class="conversation-copy"><strong>${esc(o.name||"Student")}</strong><span class="conversation-context">${esc(c.item_title||"Campus conversation")}</span><span class="conversation-preview">${esc(c.last_message||"Conversation started")}</span></span>${Number(c.unread_count||0)?`<b class="unread-badge">${Number(c.unread_count)}</b>`:""}<time>${c.updated_at?esc(new Date(c.updated_at).toLocaleDateString("en-IN",{day:"numeric",month:"short"})):""}</time></button>`}).join(""):`<div class="empty-state conversation-empty"><h3>${conversations.length?"No matching conversations":"Your inbox is ready"}</h3><p>${conversations.length?"Try a different name or item.":"Messages about approved claims and marketplace listings will appear here."}</p></div>`;
}
async function openConversation(id,refreshOnly=false){
 activeConversation=id;renderConversations();
 const c=conversations.find(x=>x.id===id),head=document.querySelector(".chat-header"),box=document.getElementById("chatMessages"),input=document.getElementById("messageInput"),send=document.querySelector("#messageForm button");
 if(!c)return;
 const o=conversationOther(c),phoneIcon='<svg class="contact-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7.2 3.8 9.8 3l2 4.5-2.1 1.6a14 14 0 0 0 5.2 5.2l1.6-2.1 4.5 2-.8 2.6a2 2 0 0 1-2 1.4A15.5 15.5 0 0 1 5.8 5.8a2 2 0 0 1 1.4-2Z"/></svg>',call=o.allow_calls?`<button class="contact-action call-action" type="button" data-start-call="${esc(c.id)}">${phoneIcon}<span>Audio call</span></button>${o.phone?`<a class="contact-action contact-secondary" href="tel:${esc(o.phone)}">${phoneIcon}<span>Phone app</span></a>`:""}`:"",email=o.allow_email&&o.email?`<a class="contact-action" href="mailto:${encodeURIComponent(o.email)}"><span aria-hidden="true">✉</span>Email</a>`:"",contactHint=!call&&!email?`<span class="contact-hint">Call and email options appear when this student shares them</span>`:"";
 if(head)head.innerHTML=`<div class="chat-peer">${avatarMarkup(o,"chat-peer-avatar")}<span class="chat-peer-copy"><strong>${esc(o.name||"Student")}</strong><span>${esc(c.item_title||"Private campus conversation")}</span></span></div><div class="chat-contact-actions">${call}${email}${contactHint}</div>`;
 try{const d=await api(`/conversations/${id}/messages`);if(box){const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<90;box.innerHTML=(d.messages||[]).map(m=>{const mine=m.sender_id===user.id;return `<div class="message-row ${mine?"outgoing":"incoming"}">${mine?"":avatarMarkup({name:m.sender_name,avatar:m.sender_avatar},"message-avatar")}<div class="bubble ${mine?"mine":""}"><p>${esc(m.content)}</p><small>${esc(new Date(m.created_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"}))}${mine?` · ${m.read_at?"Read":"Sent"}`:""}</small></div></div>`}).join("")||'<div class="empty-state"><h3>Start the conversation</h3><p>Say hello and agree on a convenient campus meeting point.</p></div>';if(nearBottom)box.scrollTop=box.scrollHeight}if(input){input.disabled=false;if(!refreshOnly&&!guestMode)input.focus()}if(send)send.disabled=false}catch(e){toast(e.message)}
}
async function sendMessage(e){e.preventDefault();if(!activeConversation)return;const input=document.getElementById("messageInput"),content=input.value.trim();if(!content)return;try{await api(`/conversations/${activeConversation}/messages`,{method:"POST",body:JSON.stringify({content})});input.value="";await openConversation(activeConversation);await loadConversations()}catch(e){toast(e.message)}}
function callUi(){let invite=document.getElementById("incomingCallPrompt");if(!invite){invite=document.createElement("div");invite.id="incomingCallPrompt";invite.className="incoming-call-prompt";invite.hidden=true;invite.setAttribute("role","status");document.body.append(invite)}let panel=document.getElementById("activeCallPanel");if(!panel){panel=document.createElement("div");panel.id="activeCallPanel";panel.className="active-call-panel";panel.hidden=true;panel.innerHTML='<span class="call-live-dot"></span><span id="activeCallLabel">Connecting audio…</span><button type="button" class="btn call-end" data-call-end>End call</button><audio id="remoteCallAudio" autoplay></audio>';document.body.append(panel)}return{invite,panel}}
function showIncomingCall(call){if(activeCall||incomingCallPrompt?.id===call.id)return;incomingCallPrompt=call;const {invite}=callUi();invite.innerHTML=`<span class="call-incoming-icon" aria-hidden="true">☎</span><span class="call-incoming-copy"><strong>${esc(call.caller_name||"Student")} is calling</strong><small>UniFind audio call</small></span><button type="button" class="btn call-accept" data-call-accept>Answer</button><button type="button" class="call-decline" data-call-decline>Decline</button>`;invite.hidden=false}
async function pollIncomingCalls(){if(!user||guestMode||activeCall)return;try{const d=await api("/calls/incoming");const call=(d.calls||[])[0];if(call)showIncomingCall(call)}catch{}}
function startCallMonitor(){if(incomingCallPoll)return;pollIncomingCalls();incomingCallPoll=setInterval(pollIncomingCalls,4000)}
function updateCallLabel(text){const label=document.getElementById("activeCallLabel");if(label)label.textContent=text}
function showCallPanel(text){const {panel}=callUi();panel.hidden=false;updateCallLabel(text)}
function closeCallUi(){const invite=document.getElementById("incomingCallPrompt"),panel=document.getElementById("activeCallPanel"),audio=document.getElementById("remoteCallAudio");if(invite){invite.hidden=true;invite.innerHTML=""}if(panel)panel.hidden=true;if(audio)audio.srcObject=null;incomingCallPrompt=null}
async function sendCallSignal(type,payload){if(!activeCall)return;await api(`/calls/${activeCall.id}/signals`,{method:"POST",body:JSON.stringify({type,payload})})}
function setupCallPeer(){callPeerConnection=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});for(const track of localCallStream.getTracks())callPeerConnection.addTrack(track,localCallStream);callPeerConnection.onicecandidate=e=>{if(e.candidate)sendCallSignal("ICE",e.candidate.toJSON()).catch(()=>{})};callPeerConnection.ontrack=e=>{const audio=document.getElementById("remoteCallAudio");if(audio){audio.srcObject=e.streams[0];audio.play().catch(()=>{})}};callPeerConnection.onconnectionstatechange=()=>{const state=callPeerConnection?.connectionState;if(state==="connected")updateCallLabel("Connected · audio call");if(state==="failed"||state==="disconnected"){updateCallLabel("Connection lost · check the network or try again");if(state==="failed")endCall("FAILED",false)}}}
async function pollCallSignals(){if(!activeCall||activeCall.polling)return;activeCall.polling=true;try{const d=await api(`/calls/${activeCall.id}/signals?after=${callSignalCursor}`);if(["ENDED","REJECTED","FAILED"].includes(d.status)){toast(d.status==="REJECTED"?"The call was declined.":"The call ended.");cleanupCall();return}for(const signal of d.signals||[]){callSignalCursor=Math.max(callSignalCursor,Number(signal.id)||0);if(signal.type==="OFFER"&&!activeCall.initiator){await callPeerConnection.setRemoteDescription(new RTCSessionDescription(signal.payload));for(const candidate of queuedIceCandidates.splice(0))await callPeerConnection.addIceCandidate(new RTCIceCandidate(candidate));const answer=await callPeerConnection.createAnswer();await callPeerConnection.setLocalDescription(answer);await sendCallSignal("ANSWER",callPeerConnection.localDescription.toJSON());updateCallLabel("Connecting audio…")}else if(signal.type==="ANSWER"&&activeCall.initiator){await callPeerConnection.setRemoteDescription(new RTCSessionDescription(signal.payload));for(const candidate of queuedIceCandidates.splice(0))await callPeerConnection.addIceCandidate(new RTCIceCandidate(candidate));updateCallLabel("Connecting audio…")}else if(signal.type==="ICE"){if(callPeerConnection.remoteDescription)await callPeerConnection.addIceCandidate(new RTCIceCandidate(signal.payload));else queuedIceCandidates.push(signal.payload)}}}catch{if(activeCall)updateCallLabel("Reconnecting…")}finally{if(activeCall)activeCall.polling=false}}
function startCallPolling(){clearInterval(callPoll);callPoll=setInterval(pollCallSignals,900);pollCallSignals()}
async function beginAudioCall(conversationId){if(activeCall)return toast("Finish the current call first.");if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)return toast("This browser does not support in-app calls. Try a supported browser or ask the student to share a phone number.");if(!window.isSecureContext)return toast("Microphone calls need HTTPS or localhost. The Phone app option is available if the student shared a number.");let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});const d=await api(`/conversations/${conversationId}/calls`,{method:"POST",body:JSON.stringify({})});activeCall={id:d.call.id,conversationId,initiator:true,polling:false};localCallStream=stream;callSignalCursor=0;queuedIceCandidates=[];setupCallPeer();showCallPanel(`Calling ${conversationOther(conversations.find(c=>c.id===conversationId)||{}).name||"student"}…`);const offer=await callPeerConnection.createOffer();await callPeerConnection.setLocalDescription(offer);await sendCallSignal("OFFER",callPeerConnection.localDescription.toJSON());startCallPolling()}catch(e){stream?.getTracks().forEach(t=>t.stop());if(activeCall)await endCall("FAILED",false);toast(e.message||"Could not start the call. Check microphone permission and try again.")}}
async function answerAudioCall(){const call=incomingCallPrompt;if(!call)return;if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)return toast("This browser does not support in-app calls.");if(!window.isSecureContext)return toast("Microphone calls need HTTPS or localhost.");try{localCallStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});await api(`/calls/${call.id}`,{method:"PATCH",body:JSON.stringify({status:"ACCEPTED"})});activeCall={id:call.id,conversationId:call.conversation_id,initiator:false,polling:false};callSignalCursor=0;queuedIceCandidates=[];setupCallPeer();closeCallUi();showCallPanel(`On a call with ${call.caller_name||"student"}`);startCallPolling()}catch(e){localCallStream?.getTracks().forEach(t=>t.stop());await api(`/calls/${call.id}`,{method:"PATCH",body:JSON.stringify({status:"FAILED"})}).catch(()=>{});closeCallUi();toast(e.message||"Could not answer. Check microphone permission and try again.")}}
async function rejectAudioCall(){const call=incomingCallPrompt;if(call)await api(`/calls/${call.id}`,{method:"PATCH",body:JSON.stringify({status:"REJECTED"})}).catch(()=>{});closeCallUi()}
async function endCall(status="ENDED",notify=true){if(activeCall)await api(`/calls/${activeCall.id}`,{method:"PATCH",body:JSON.stringify({status})}).catch(()=>{});cleanupCall();if(notify)toast("Call ended.")}
function cleanupCall(){clearInterval(callPoll);callPoll=null;callPeerConnection?.close();callPeerConnection=null;localCallStream?.getTracks().forEach(t=>t.stop());localCallStream=null;activeCall=null;callSignalCursor=0;queuedIceCandidates=[];closeCallUi()}
async function messageWithUser(otherUserId,itemId,marketplaceListingId){if(!user){toast("Sign in to message students.");document.getElementById("authScreen").classList.remove("hidden");return}if(!otherUserId)return toast("The other participant is not available.");try{const d=await api("/conversations",{method:"POST",body:JSON.stringify({otherUserId,itemId,marketplaceListingId})});await loadConversations();navigate("messages");await openConversation(d.conversationId)}catch(e){toast(e.message)}}

function renderHome(){let q=(document.getElementById("homeSearch")?.value||"").trim().toLowerCase();let f=i=>{let h=[i.title,i.description,i.location,cat(i.category)].join(" ").toLowerCase();return(!q||h.includes(q))&&(homeFilter==="all"||homeFilter===i.type||homeFilter===i.category)};grid("homeLostGrid",active().filter(i=>i.type==="lost").filter(f).slice(0,6),"No active lost reports","No lost items match this search or filter.");grid("homeFoundGrid",active().filter(i=>i.type==="found").filter(f).slice(0,6),"No active found reports","No found items match this search or filter.")}
function renderMarketplace(){const gridEl=document.getElementById("marketGrid");if(!gridEl)return;const q=(document.getElementById("marketSearch")?.value||"").trim().toLowerCase(),category=(document.getElementById("marketCategory")?.value||"all").toLowerCase(),sort=document.getElementById("marketSort")?.value||"newest";let rows=listings.filter(l=>(marketFilter==="all"||l.type===marketFilter)&&(!q||[l.title,l.description,l.category,l.location].join(" ").toLowerCase().includes(q))&&(category==="all"||String(l.category).toLowerCase()===category));rows.sort((a,b)=>sort==="price-low"?a.price-b.price:sort==="price-high"?b.price-a.price:new Date(b.created_at)-new Date(a.created_at));document.getElementById("marketCount").textContent=`${rows.length} listing${rows.length===1?"":"s"}`;gridEl.innerHTML=rows.length?rows.map(l=>{const own=!!user&&l.ownerId===user.id,price=`₹${l.price.toLocaleString("en-IN")}${l.type==="RENT"?` / ${esc(l.price_period||"month")}`:""}`,art=/book|note|textbook/i.test(l.title+" "+l.category)?"📚":/cycle|bike/i.test(l.title)?"🚲":/electronic|calculator|laptop|phone/i.test(l.title+" "+l.category)?"🎧":"🎒";return `<article class="market-card"><div class="market-image">${l.image?`<img src="${esc(l.image)}" alt="Photo of ${esc(l.title)}" loading="lazy" decoding="async" onerror="this.style.display='none';this.parentElement.classList.add('image-fallback')">`:`<div class="placeholder-image" aria-label="No item photo"><span>${art}</span><small>Photo not added</small></div>`}<span class="market-type ${l.type.toLowerCase()}">${l.type==="RENT"?"For rent":"For sale"}</span></div><div class="market-card-body"><div class="market-card-heading"><h3>${esc(l.title)}</h3><strong>${price}</strong></div><p class="market-description">${esc(l.description)}</p><div class="market-meta"><span>⌖ ${esc(l.location)}</span><span>${esc(l.category)}</span></div><div class="market-owner">${avatarMarkup({name:l.owner_name,avatar:l.owner_avatar},"market-avatar")}<span>Listed by <strong>${esc(l.owner_name||"Student")}</strong></span></div><div class="market-card-actions">${own?`<button class="btn btn-outline" data-listing-status="${esc(l.id)}" data-status="${l.type==="RENT"?"RENTED":"SOLD"}">Mark ${l.type==="RENT"?"rented":"sold"}</button><button class="text-btn" data-listing-status="${esc(l.id)}" data-status="CLOSED">Close listing</button>`:`<button class="btn btn-success" data-market-message="${esc(l.ownerId)}" data-market-listing="${esc(l.id)}" ${l.allow_messages===false?"disabled title=\"This student has disabled in-app messages\"":""}>${l.type==="RENT"?"Ask about rental":"Ask to buy"}</button>`}</div></div></article>`}).join(""):`<div class="empty-state market-empty"><div class="empty-icon">◇</div><h3>${listings.length?"No listings match those filters":"The marketplace is ready for its first listing"}</h3><p>${listings.length?"Try a different search or category.":"Be the first to share a useful item with the campus community."}</p>${!guestMode?`<button class="btn btn-success" data-create-listing>＋ Create a listing</button>`:`<button class="btn btn-outline" data-auth-needed>Sign in to create a listing</button>`}</div>`}
function openListingForm(){if(!user){toast("Sign in to create a marketplace listing.");document.getElementById("authScreen").classList.remove("hidden");return}document.getElementById("listingForm").reset();document.getElementById("listingError").textContent="";document.getElementById("listingUploadPreview").textContent="＋";document.getElementById("listingUploadText").textContent="Add a clear item photo";document.getElementById("rentalPeriodLabel").classList.add("hidden-field");modal("listingModal")}
