function renderMine(){let m=items.filter(i=>i.ownerId===user.id);grid("myLostGrid",m.filter(i=>i.type==="lost"),"You haven't reported a lost item","Use “I Lost Something” to create a report.");grid("myFoundGrid",m.filter(i=>i.type==="found"),"You haven't reported a found item","Use “I Found Something” to create a report.");["profileLostCount","profileFoundCount","profileReturnedCount"].forEach(id=>{let e=document.getElementById(id);if(e)e.textContent=id==="profileLostCount"?m.filter(i=>i.type==="lost").length:id==="profileFoundCount"?m.filter(i=>i.type==="found").length:m.filter(i=>i.status==="returned").length})}
function search(){
 let q=document.getElementById("searchPageInput").value.trim().toLowerCase(),st=document.getElementById("searchStatus").value,ca=document.getElementById("searchCategory").value,lo=document.getElementById("searchLocation").value,so=document.getElementById("searchSort").value;
 let r=active().filter(i=>{let h=[i.title,i.description,i.details,i.location,cat(i.category)].join(" ").toLowerCase();return(!q||h.includes(q))&&(st==="all"||i.type===st)&&(ca==="all"||i.category===ca)&&(lo==="all"||i.location===lo)}).sort((a,b)=>so==="newest"?new Date(b.createdAt)-new Date(a.createdAt):new Date(a.createdAt)-new Date(b.createdAt));
 document.getElementById("resultCount").textContent=`${r.length} result${r.length===1?"":"s"}`;document.getElementById("searchHint").textContent=q?`Results for “${q}”`:"Showing active reports";grid("searchResults",r,"No matching items","Try another keyword or remove a filter.")
}
async function matches(){
 let lost=items.filter(i=>i.ownerId===user.id&&i.type==="lost"&&i.status==="active"),out=[];
 for(const l of lost){try{let d=await api(`/items/${l.id}/matches`);(d.matches||[]).forEach(x=>out.push({l,f:mapItem(x.item),s:x.score,reasons:x.reasons||[]}))}catch{}}
 out.sort((a,b)=>b.s-a.s);let e=document.getElementById("matchesList");if(!e)return;e.innerHTML=out.length?out.map(x=>`<article class="match-card"><div class="match-thumb">${x.f.image?`<img src="${esc(x.f.image)}" alt="Photo of ${esc(x.f.title)}" loading="lazy" decoding="async" onerror="this.style.display='none';this.parentElement.classList.add('image-fallback')">`:`<div class="placeholder-image">◈</div>`}</div><div class="match-content"><h3>${esc(x.f.title)}</h3><p>Potential match for <strong>${esc(x.l.title)}</strong>. ${esc(x.reasons.join(", ")||"Similar item details contributed to this suggestion.")}.</p><button class="card-link" data-view-item="${esc(x.f.id)}">Review found item →</button></div><div class="match-score">${x.s}%<small>POTENTIAL MATCH</small></div></article>`).join(""):`<div class="empty-state"><div class="empty-icon">✦</div><h3>No strong potential matches yet</h3><p>Keep your lost report active. New found reports can create a match later.</p></div>`
}
function renderNotes(){let e=document.getElementById("notificationsList");if(!e)return;e.innerHTML=notes.length?notes.map(n=>`<article class="notification ${n.unread?"unread":""}"><div class="notification-icon">${String(n.type||"").includes("CLAIM")?"✓":"✦"}</div><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><time>${esc(new Date(n.time).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"}))}</time></div></article>`).join(""):`<div class="empty-state"><div class="empty-icon">♢</div><h3>You're all caught up</h3><p>New updates will appear here.</p></div>`;let b=document.getElementById("notificationCount"),u=notes.filter(n=>n.unread).length;if(b){b.textContent=u;b.style.display=u?"grid":"none"}}
async function markNotificationsRead(){for(const n of notes.filter(n=>n.unread)){try{await api(`/notifications/${n.id}/read`,{method:"PATCH"})}catch{}}notes.forEach(n=>n.unread=false);renderNotes()}
function report(type){
 if(!user){toast("Sign in to report a lost or found item.");document.getElementById("authScreen").classList.remove("hidden");return}
 document.getElementById("reportForm").reset();document.getElementById("uploadPreview").innerHTML="＋";document.getElementById("uploadText").textContent="Add a photo";document.getElementById("formError").textContent="";document.getElementById("reportType").value=type;document.getElementById("reportIcon").textContent=type==="lost"?"↗":"↙";document.getElementById("reportEyebrow").textContent=type==="lost"?"LOST REPORT":"FOUND REPORT";document.getElementById("reportTitle").textContent=type==="lost"?"Report a Lost Item":"Report a Found Item";document.getElementById("reportSubtitle").textContent=type==="lost"?"Give enough information for other students to recognize the item.":"Help the owner recognize and safely recover what you found.";document.getElementById("storageLabel").classList.toggle("hidden-field",type==="lost");document.getElementById("storageLocation").required=type!=="lost";document.getElementById("submitReportBtn").textContent=type==="lost"?"Publish Lost Report":"Publish Found Report";document.getElementById("submitReportBtn").className=`btn ${type==="lost"?"btn-danger":"btn-success"}`;document.getElementById("eventDate").valueAsDate=new Date();modal("reportModal")
}
function detail(id){
 let i=items.find(x=>x.id===id);if(!i)return;let own=!!user&&i.ownerId===user.id,claim=!!user&&i.type==="found"&&!own&&i.status==="active";
 document.getElementById("itemDetailContent").innerHTML=`<div class="detail-hero"><div class="detail-photo">${i.image?`<img src="${esc(i.image)}" alt="Photo of ${esc(i.title)}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('image-fallback')">`:`<div class="placeholder-image">◈</div>`}</div><div class="detail-main"><span class="status-badge ${i.type}" style="position:static;display:inline-block;">${i.status==="returned"?"Returned":i.status==="claimed"?"Claimed":i.type==="lost"?"Lost":"Found"}</span><h2>${esc(i.title)}</h2><p>${esc(i.description)}</p><div class="detail-meta"><span>📁 ${esc(cat(i.category))}</span><span>📍 ${esc(i.location)}</span><span>📅 ${date(i.date)}${i.time?" · "+esc(i.time):""}</span>${i.type==="found"&&i.storageLocation?`<span>🔐 Current location: ${esc(i.storageLocation)}</span>`:""}</div><div class="detail-note"><strong>DISTINGUISHING DETAILS</strong><p>${esc(i.details||"Private identifying details are protected.")}</p></div>${claim?`<button class="btn btn-success" data-claim-item="${esc(i.id)}">This might be mine</button>`:own&&i.status==="active"?`<button class="btn btn-outline" data-mark-returned="${esc(i.id)}">Mark as returned</button>`:guestMode?`<button class="btn btn-outline" data-auth-needed>Sign in to claim or report an item</button>`:""}</div></div>`;modal("itemModal")
}
function claimOpen(id){let i=items.find(x=>x.id===id);if(!i||i.type!=="found"||i.ownerId===user.id||i.status!=="active"){toast("This item cannot be claimed.");return}if(user?.verificationStatus!=="VERIFIED"){toast("Verify your Somaiya ID before claiming an item.");navigate("profile");return}document.getElementById("claimItemId").value=id;document.getElementById("claimReason").value="";document.getElementById("claimError").textContent="";document.getElementById("claimItemPreview").textContent=`${i.title} · ${i.location}`;modal("itemModal",false);modal("claimModal")}
