async function loadProfile(){
 let d=await api("/profile"),u=d.user;user=u;
 const set=(id,v)=>{let e=document.getElementById(id);if(e)e.value=v??""}; 
 document.getElementById("profileName").textContent=u.name||"Student";document.getElementById("profileEmail").textContent=u.email||"";
 document.getElementById("profileVerification").textContent=(u.verificationStatus||"PENDING")==="VERIFIED"?"✓ Verified university account":"✓ Account verification: "+String(u.verificationStatus||"PENDING").toLowerCase();
 set("profileEditName",u.name);set("profileEditMemberId",u.memberId);set("profileEditPhone",u.phone);set("profileEditDepartment",u.department);set("profileEditCourse",u.course);set("profileEditYearBatch",u.yearBatch);
 document.getElementById("allowMessages") && (document.getElementById("allowMessages").checked=!!u.contactPreferences?.messages); document.getElementById("allowCalls") && (document.getElementById("allowCalls").checked=!!u.contactPreferences?.calls); document.getElementById("allowEmail") && (document.getElementById("allowEmail").checked=!!u.contactPreferences?.email);
 let av=document.getElementById("profileAvatar");if(av){let initials=(u.name||"S").split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase();av.classList.toggle("has-photo",!!u.avatar);av.replaceChildren();if(u.avatar){const photo=document.createElement("img");photo.src=imageUrl(u.avatar);photo.alt=`${u.name||"Student"} profile photo`;photo.decoding="async";photo.style.cssText="position:absolute;inset:0;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:cover;border-radius:50%";photo.onerror=()=>{photo.remove();av.textContent=initials};av.append(photo)}else av.textContent=initials}
 document.getElementById("idCardStatus").textContent=u.idCard?(u.idCardOcrText?"Uploaded — details extracted; verification status: "+String(u.verificationStatus||"PENDING").toLowerCase():"Uploaded — awaiting verification"):"Not uploaded";
}
