document.getElementById("listingType")?.addEventListener("change",e=>document.getElementById("rentalPeriodLabel").classList.toggle("hidden-field",e.target.value!=="RENT"));
document.getElementById("listingImage")?.addEventListener("change",e=>{const f=e.target.files[0];if(!f)return;if(!["image/jpeg","image/png","image/webp"].includes(f.type)||f.size>5*1024*1024){toast("Choose a JPG, PNG or WEBP image under 5 MB.");e.target.value="";return}const r=new FileReader();r.onload=()=>{document.getElementById("listingUploadPreview").innerHTML=`<img src="${r.result}" alt="Selected listing photo preview">`;document.getElementById("listingUploadText").textContent="Photo selected"};r.readAsDataURL(f)});
document.getElementById("marketSearch")?.addEventListener("input",renderMarketplace);document.getElementById("marketCategory")?.addEventListener("change",renderMarketplace);document.getElementById("marketSort")?.addEventListener("change",renderMarketplace);document.getElementById("conversationSearch")?.addEventListener("input",renderConversations);
document.getElementById("sendSignupOtpBtn")?.addEventListener("click",requestSignupOtp);
document.getElementById("signupForm")?.addEventListener("submit",signup);
document.getElementById("signupIdCard")?.addEventListener("change",previewSignupId);
document.getElementById("forgotPasswordBtn")?.addEventListener("click",forgotPassword);
document.getElementById("messageForm")?.addEventListener("submit",sendMessage);document.getElementById("saveContactPrefs")?.addEventListener("click",saveContactPrefs);
document.getElementById("reportForm").addEventListener("submit",submitReport);
document.getElementById("claimForm").addEventListener("submit",submitClaim);
document.getElementById("itemImage").addEventListener("change",upload);
document.getElementById("homeSearch").addEventListener("input",renderHome);
document.getElementById("homeSearchBtn").addEventListener("click",()=>{document.getElementById("searchPageInput").value=document.getElementById("homeSearch").value;navigate("search")});
document.getElementById("homeSearch").addEventListener("keydown",e=>{if(e.key==="Enter")document.getElementById("homeSearchBtn").click()});
document.getElementById("searchPageBtn").addEventListener("click",search);document.getElementById("searchPageInput").addEventListener("keydown",e=>{if(e.key==="Enter")search()});["searchStatus","searchCategory","searchLocation","searchSort"].forEach(id=>document.getElementById(id).addEventListener("change",search));
document.getElementById("logoutBtn").addEventListener("click",()=>logout());
document.getElementById("loginForm").addEventListener("submit",login);
document.getElementById("avatarBtn").addEventListener("click",()=>document.getElementById("avatarInput").click());
document.getElementById("avatarInput").addEventListener("change",uploadAvatar);
document.getElementById("idCardBtn").addEventListener("click",()=>document.getElementById("idCardInput").click());
document.getElementById("idCardInput").addEventListener("change",uploadId);
document.getElementById("profileForm").addEventListener("submit",saveProfile);
document.getElementById("claimHelpBtn")?.addEventListener("click",()=>toast("Moderator contact will be connected in the next block."));
document.getElementById("reportHelpBtn")?.addEventListener("click",()=>toast("Issue reporting will be connected in the next block."));
document.querySelectorAll(".modal-backdrop").forEach(b=>b.addEventListener("click",e=>{if(e.target===b)modal(b,false)}));
document.addEventListener("keydown",e=>{if(e.key==="Escape")document.querySelectorAll(".modal-backdrop.open").forEach(m=>modal(m,false))});
window.addEventListener("popstate",()=>showPage(location.hash.slice(1)||"home"));window.addEventListener("hashchange",()=>showPage(location.hash.slice(1)||"home"));

(async function boot(){
 handleAuthCallback();
 if(!token){document.getElementById("authScreen").classList.remove("hidden");return}
 try{await refresh();document.getElementById("authScreen").classList.add("hidden");showPage(location.hash.slice(1)||"home")}catch(err){console.error(err);logout(false)}
})();
